package com.eread.cloud.controller;

import com.eread.cloud.document.ReadingProgressDoc;
import com.eread.cloud.dto.ProgressUpdateDto;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.data.mongodb.core.query.Criteria;
import org.springframework.data.mongodb.core.query.Query;
import org.springframework.data.mongodb.core.query.Update;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/mongo/reader")
public class ReadingProgressController {

    private final MongoTemplate mongoTemplate;

    public ReadingProgressController(MongoTemplate mongoTemplate) {
        this.mongoTemplate = mongoTemplate;
    }

    @PatchMapping("/{documentId}/progress")
    public ResponseEntity<String> updateReadingProgress(
            @PathVariable String documentId,
            @RequestBody ProgressUpdateDto dto,
            Authentication authentication) {
        Query query = new Query(new Criteria().andOperator(
                Criteria.where("documentId").is(documentId),
                Criteria.where("userId").is(authentication.getName())
        ));
        Update update = new Update()
                .set("currentPage", dto.getCurrentPage())
                .set("highlightColor", dto.getHighlightColor());
        mongoTemplate.updateFirst(query, update, ReadingProgressDoc.class);
        return ResponseEntity.ok("Reading progress synchronized");
    }
}
